    val hun = if (num / 100 > 0) num / 100 else null
    val ten = if ((num % 100) / 10 > 0) (num % 100) / 10 else null
    val one = num % 10
    if (ten == null && hun == null) {
        return one in pos[0] || one in pos[1] || one in pos[2]
    }
    if (hun == null) {
        return one in pos[0] && (ten in pos[1] || ten in pos[2]) ||
                one in pos[1] && (ten in pos[0] || ten in pos[2]) ||
                one in pos[2] && (ten in pos[0] || ten in pos[1])
    }
    return one in pos[0] && ten in pos[1] && hun in pos[2] ||
            one in pos[1] && ten in pos[0] && hun in pos[2] ||
            one in pos[0] && ten in pos[2] && hun in pos[1] ||
            one in pos[1] && ten in pos[2] && hun in pos[0] ||
            one in pos[2] && ten in pos[1] && hun in pos[0] ||
            one in pos[2] && ten in pos[0] && hun in pos[1]
}
